J('sanctuaire: énigme lumière',"(async()=>{const L=__lumen;L.tpZone('sanctuaire',[24,5]);await T.tick(300);return T.solve('sd_light')})()","true")
J('sanctuaire: gardien clé',"(async()=>{const L=__lumen;L.tpZone('sanctuaire',[5,14]);await T.tick(1000);const k=await T.cutAndKill(['gardien'],40000);return k})()")
