J('porte à clé',"(async()=>{const L=__lumen;const [x,y]=L.isl.gates.sd_key.cells[0];return await T.useTarget('lock',x*2,(y-1)*2-0.4)+' ouverte='+L.G.isGateOpen('sd_key')})()","ouverte=true")
J('chambre cachée (roches c)',"(async()=>{const L=__lumen;let n=0;const zi=L.G.zones.findIndex(z=>z.id==='sanctuaire');L.give('marteau',1);L.G.equip('marteau',true);L.tpZone('sanctuaire',[4,19]);await T.tick(600);for(let y=0;y<L.isl.h;y++)for(let x=0;x<L.isl.w;x++)if(L.isl.terrain[y][x]==='c'&&L.isl.zoneAt[y][x]===zi){L.P.x=x*2;L.P.z=y*2-1.3;L.P.face=0;L.st.player.hp=999;for(let i=0;i<6&&L.isl.terrain[y][x]==='c';i++){L.combat.melee({mult:1});await T.tick(150);}n++;break;}return 'roche brisée? '+n+' broken='+Object.keys(L.st.world.broken).length})()")
