J('énigmes g3..g9 (+secrets)',"""(async()=>{const L=__lumen,out=[];const order=['z3','z4','z5','z6','z7','z8','z9'];
  for(const z of order){L.tpZone(z);await T.tick(250);const g=L.G.zones.find(x=>x.id===z).ents.find(e=>e.gate&&!e.optional).gate;out.push(g+':'+T.solve(g));}
  return out.join(' ')+' '+T.q('q_phare')})()""","active:lentille")
J('secrets: pages et éclats',"""(async()=>{const L=__lumen,out=[];
  for(const [z,g] of [['z3','s1'],['z4','s2'],['z8','s3']]){L.tpZone(z);await T.tick(250);out.push(g+':'+T.solve(g));}
  return out.join(' ')+' comptes: '+JSON.stringify({gates:Object.keys(L.st.world.gates).length})})()""")
J('chambres secrètes t1..t3',"""(async()=>{const L=__lumen,out=[];for(const [z,g] of [['s1','t1'],['s2','t2'],['s3','t3']]){L.tpZone(z);await T.tick(300);out.push(g+':'+T.solve(g));}return out.join(' ')})()""")
J('ramasser tout (éclats/pages/lueur) en réel',"""(async()=>{const L=__lumen;let n=0;for(const e of L.isl.ents.filter(e=>['shard','page','wisp'].includes(e.t))){const z=L.G.zones[e.zone];L.tpZone(z.id,[e.x-z.ox,e.y-z.oy]);await T.tick(130);if(L.S.mode==='screen'||L.S.mode==='dialog'){L.G.screens.close();}n++;}
  L.G.screens.close();await T.tick(200);return n+' shards='+L.G.counts('shards')+'/'+L.G.countAll('shard')+' pages='+L.G.counts('pages')+' pageList='+JSON.stringify(L.G.pageList().map(p=>p.found))})()""")
